from pathlib import Path
p=Path(__file__).parent;training=json.loads((p/'exit_optimization_results.json').read_text());parent=p.parent if (p.parent/'build_rotation_report.py').exists() else Path('/Users/gavinz/git/finance/hedge_codex/straddle/rotation')
tree=ast.parse((parent/'build_rotation_report.py').read_text());v={}
for n in tree.body:
 if isinstance(n,ast.Assign) and isinstance(n.value,ast.Constant):
  for t in n.targets:
   if isinstance(t,ast.Name):v[t.id]=n.value.value
css=v['css'];chart=v['js'].split('let setups={};',1)[1].split('function drawEquity()',1)[0]
latest_path=p/'best_strategy_latest.json';selected=next(r for r in training['results'] if r['rule']['id']==training['best'])
latest=json.loads(latest_path.read_text()) if latest_path.exists() else dict(selection_end=training['end'],data_end=training['end'],selected_rule_id=training['best'],requested_end=training['end'],result=selected)
assert latest['selected_rule_id']==training['best'] and latest['result']['rule']==selected['rule']
D=dict(start=training['start'],selection_end=training['end'],rules_count=training['rules_count'],best=training['best'],comparison=[dict(rule=r['rule'],stats=r['stats']) for r in training['results']],latest=latest)
body='''<main><div class="muted">SKHY · 最终报告5 · 固定平方根时间选约</div><h1>策略选优与最优策略逐笔操作</h1><p id="overview"></p>
<section id="part1"><h2>第一部分：不同策略对比，选出最优策略</h2><p id="selectionDate" class="note"></p><div id="chosen"></div><h3>44组策略的原始选优结果</h3><p>所有策略每次1 Call＋1 Put，以费用／√剩余天数选择到期日，费用比上限12%。比较不同涨跌止盈目标、35%止损及到期前3天／2天10:00或15:30强平。止盈目标是组合相对本次期权成本的盈利百分比；到期周三、周四、周五分别乘75%、50%、25%。</p><div class="scroll" id="comparison"></div><p class="muted">本部分保留原训练区间与原排名。结果是样本内比较，不保证未来表现。强平规则会剔除已经进入强平窗口的合约，再重新选约；同一组交易不会事后改写卖价。</p></section>
<section id="part2"><h2>第二部分：最优策略的最新交易与每轮操作</h2><p id="latestDate" class="note"></p><div class="cards" id="cards"></div><h3>最优策略累计毛收益</h3><div class="chart"><canvas id="equity"></canvas><div class="tip" id="equitytip"></div></div><p class="muted">曲线包括已实现收益和持仓估值；退出后延续已实现收益，重开后加入新一轮浮盈亏。鼠标查看有效观察值及时间。</p><h3>逐笔买卖：时间、股价、费用和盈亏</h3><div class="scroll" id="ledger"></div><p class="muted">仅显示已选定的最优策略。每行一轮开仓；时间均为美东。仍持仓行显示估值时间和估值金额，并非实际卖出。期权每股报价×100＝每张金额。</p><h3>每个轮回的完整操作记录</h3><div id="rounds"></div><h3>单轮毛收益与股票涨跌幅</h3><div class="toolbar"><label>轮回 <select id="trade"></select></label></div><div id="tradeinfo"></div><div class="legend"><span style="color:#58dcc0">绿色：组合毛收益$ · 左轴</span><span style="color:#54afff">蓝色：股票涨跌% · 右轴</span></div><div class="chart"><canvas id="tradechart"></canvas><div class="tip" id="tradetip"></div></div><h3>轮空记录</h3><div class="scroll" id="skips"></div><details><summary>执行口径与复现说明</summary><p>每次只持有一组期权，先平仓再重开。入场价格来自信号至少一分钟后的首个股票、Call、Put共同成交分钟开盘价。选约及信号用当时已完成的分钟，两腿价格年龄不超过10分钟。平仓后下一个10分钟检查点、且不早于10:00重开；15:30后顺延下一交易日。费用过贵或当日无合格成交分钟则下一交易日10:00重试。周五不新买0DTE，只考虑下周五。</p><p>期末仍持仓用当日两腿最后成交价估值，详情列出价龄。到期结算按内在价值。历史成交数据不保证实盘按该价成交；止盈和止损是信号，不是成交收益保证。收益统一为毛收益，不扣交易费用，不计算年化。最大回撤按可用观察点估计，缺价期间可能低估实际回撤。</p><p><a href="best_strategy_latest.json">最优策略最新明细</a> · <a href="oct12_market_provenance.json">10/12行情来源与核对记录</a> · <a href="https://ca.investing.com/equities/sk-hynix-adr-options">收盘期权链核对</a> · <a href="exit_optimization_results.json">原始策略对比结果</a> · <a href="README.md">复现说明</a> · <a href="../skhy_report4_rotation.html">报告4</a></p></details></section></main>'''
js=r'''
const $=id=>document.getElementById(id),fmt=(v,n=2)=>v==null?'—':Number(v).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}),money=v=>'$'+fmt(v),dt=s=>s?s.slice(0,16).replace('T',' '):'—',pc=v=>fmt(v)+'%',color=v=>v>=0?'pos':'neg';
const table=(h,rs)=>'<table><thead><tr>'+h.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rs.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
const L=D.latest.result,rule=L.rule,base=D.comparison.find(r=>r.rule.id===D.best),ranked=[...D.comparison].sort((a,b)=>b.stats.total-a.stats.total||a.stats.drawdown-b.stats.drawdown),forced=ranked.find(r=>r.rule.days!=null);
const force=r=>r.days==null?'不强平':`提前${r.days}天 ${r.clock}`;
const describe=r=>`${r.up==null?'仅按时间平仓':`初始涨侧盈利${r.up}%／跌侧盈利${r.down}%，到期周三×75%、周四×50%、周五×25%`}；${r.stop==null?'不设止损':`亏损${r.stop}%触发止损`}；${force(r)}。`;
$('overview').textContent=`每次1 Call＋1 Put｜费用／√剩余天数选约｜12%费用上限｜最优策略 ${D.best}`;
$('selectionDate').textContent=`选优区间：${D.start}至${D.selection_end}。本次保留此前44组策略的排名和选定参数，使用后续行情更新第二部分的交易与估值。`;
$('chosen').innerHTML=`<p><strong>${D.best}：${describe(rule)}</strong></p><p>原选优区间毛收益${money(base.stats.total)}，观察点最大回撤${money(base.stats.drawdown)}。如果要求强平，原比较中最高为${forced.rule.id}：${describe(forced.rule)}，毛收益${money(forced.stats.total)}。</p>`;
$('comparison').innerHTML=table(['排名','编号','涨／跌初始目标','止损','强平时点','选优期合计毛收益','已实现','期末浮盈亏','开仓／平仓','最大回撤','最差单笔'],ranked.map((r,i)=>{let q=r.rule,s=r.stats;return[i+1,q.id,q.up==null?'仅按时间':q.up+'% / '+q.down+'%',q.stop==null?'无':q.stop+'%',force(q),`<b class="${color(s.total)}">${money(s.total)}</b>`,money(s.realized),money(s.floating),s.positions+' / '+s.closed,money(s.drawdown),money(s.worst)]}));
let coverage=D.latest.requested_end&&D.latest.requested_end>D.latest.data_end?`已请求截至${D.latest.requested_end}的行情，接口目前仅返回至${D.latest.data_end}。`:'';
$('latestDate').textContent=`固定策略${D.best}的交易数据更新至美东${D.latest.data_end}。${coverage}${D.latest.source_note||''}`;
$('cards').innerHTML=[['最新合计毛收益',money(L.stats.total)],['已实现毛收益',money(L.stats.realized)],['持仓浮盈亏',money(L.stats.floating)],['开仓／已平仓',L.stats.positions+' / '+L.stats.closed]].map(([a,b])=>`<div class="card">${a}<strong>${b}</strong></div>`).join('');
const exitLabel=t=>t.status==='仍持仓估值'?'估值':t.status==='到期结算'?'结算':'卖出';
$('ledger').innerHTML=table(['轮回','买入ET','买入股价','行权价K','到期日','卖出／结算／估值ET','退出／估值股价','Call买→卖／估值','Put买→卖／估值','支出','回收／估值','毛盈亏','收益率','状态／原因'],L.trades.map(t=>[t.id,dt(t.entry.time),fmt(t.entry.stock),fmt(t.contract.strike),t.contract.expiry,dt(t.exit.time),fmt(t.exit.stock),fmt(t.entry.call)+' → '+fmt(t.exit.call),fmt(t.entry.put)+' → '+fmt(t.exit.put),money(t.entry.value),money(t.exit.value),`<b class="${color(t.gross)}">${money(t.gross)}</b>`,pc(t.roi),t.status+' / '+(t.signal?.reason||'—')]));
$('rounds').innerHTML=L.trades.map(t=>{let candidates=Object.entries(t.decision.candidates).map(([k,q])=>[k==='near'?'本周五':'下周五',q.expiry,fmt(q.strike),fmt(q.stock),fmt(q.call),fmt(q.put),money(q.cost),pc(q.pct),fmt(q.dte,2),fmt(q.score,5)]);let next=L.trades[t.id];let sig=t.signal?`${dt(t.signal.time)}，${t.signal.reason}${t.signal.roi==null?'':`，当时组合收益率${pc(t.signal.roi)}`}${t.signal.target==null?'':`，参考目标${pc(t.signal.target)}`}`:'尚未触发有效平仓信号';let age=t.exit.ages?`本次估值Call／Put价格年龄${fmt(t.exit.ages.call,0)}／${fmt(t.exit.ages.put,0)}分钟。`:'';return`<details style="margin:15px 0"><summary>第${t.id}轮：${dt(t.entry.time)} → ${dt(t.exit.time)}｜${t.status}｜${money(t.gross)}</summary><p>① ${dt(t.decision.time)}选约：买${t.contract.expiry}到期、K=${fmt(t.contract.strike)}的1 Call＋1 Put。选择费用／√剩余天数较低且费用≤12%的合格候选。下面是决策时已完成的成交报价，实际买入费用可能不同。</p><div class="scroll">${table(['候选','到期日','K','观察股价','Call价','Put价','预计费用','费用比','剩余自然日','时间折算费用'],candidates)}</div><p>② ${dt(t.entry.time)}买入：股价${money(t.entry.stock)}，Call ${money(t.entry.call)}×100＝${money(t.entry.call*100)}，Put ${money(t.entry.put)}×100＝${money(t.entry.put*100)}，总支出${money(t.entry.value)}。</p><p>③ 退出信号：${sig}。</p><p>④ ${dt(t.exit.time)}${exitLabel(t)}：股价${money(t.exit.stock)}，Call ${money(t.exit.call)}，Put ${money(t.exit.put)}，组合${exitLabel(t)}金额${money(t.exit.value)}。${age}</p><p>⑤ Call盈亏${money(t.call_pnl)}，Put盈亏${money(t.put_pnl)}，合计${money(t.gross)}，收益率${pc(t.roi)}。</p><p>⑥ ${t.status==='仍持仓估值'?'本轮尚持仓，没有重新开仓。':next?`下一轮实际买入时间${dt(next.entry.time)}；期间若有轮空见下表。`:'截至当前数据末尾暂无下一轮买入。'}</p></details>`}).join('');
$('skips').innerHTML=table(['美东观察时间','处理','原因'],L.decisions.filter(x=>x.action==='轮空').map(x=>[dt(x.time),x.action,x.reason]));
$('trade').innerHTML=L.trades.map((t,i)=>`<option value="${i}">第${t.id}轮 ${dt(t.entry.time)} · ${money(t.gross)} · ${t.status}</option>`).join('');$('trade').value=String(L.trades.length-1);let trade;
function chooseTrade(){trade=L.trades[+$('trade').value||0];if(!trade)return;let t=trade;$('tradeinfo').textContent=`第${t.id}轮：股票${money(t.entry.stock)} → ${money(t.exit.stock)}；Call盈亏${money(t.call_pnl)}、Put盈亏${money(t.put_pnl)}、合计${money(t.gross)}。`;drawTrade()}
let setups={};
'''+chart+r'''
function drawEquity(){chart('equity','equitytip',[{name:'最优策略累计毛收益',color:'#58dcc0',points:L.equity}])}
function drawTrade(){if(!trade)return;let t=trade,pts=[{time:t.entry.time,pnl:0,stock:t.entry.stock},...t.curve,{time:t.exit.time,pnl:t.gross,stock:t.exit.stock}];chart('tradechart','tradetip',[{name:'组合毛收益',color:'#58dcc0',points:pts.map(p=>({time:p.time,value:p.pnl}))},{name:'股票涨跌',color:'#54afff',axis:1,points:pts.map(p=>({time:p.time,value:(p.stock/t.entry.stock-1)*100}))}],true)}
$('trade').onchange=chooseTrade;chooseTrade();drawEquity();window.addEventListener('resize',()=>{drawEquity();drawTrade()});
'''
result='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SKHY最终报告：策略对比与最优策略最新操作</title><style>'+css+'</style></head><body>'+body+'<script>const D='+json.dumps(D,ensure_ascii=False,allow_nan=False).replace('</','<\\/')+';\n'+js+'</script></body></html>'
(p/'skhy_report5_exit_optimization.html').write_text(result);print('Built two-part final report',D['selection_end'],latest['data_end'],training['best'])
